initial_condition:
with {
    the SUT containing a Hosted @context and the default Cached Core Context.
            }

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Delete a @context with Response Status Code set to 204     and
        Delete a @context with Response reason set to 'No Content'     and
        Delete a @context with Response does not contain a body
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/jsonldContexts/{contextId}'
        method set to 'DELETE'
        Delete a @context whose 'URI' set to '${uri}'
}
